import React, { useState, useEffect } from 'react';
import { Chip, Tooltip } from '@mui/material';
import TimerIcon from '@mui/icons-material/Timer';
import BlockIcon from '@mui/icons-material/Block';
import DemoIcon from '@mui/icons-material/NewReleases';
import { format, formatDistanceToNow, isPast } from 'date-fns';
import { useTranslation } from 'react-i18next';
import { ru, enUS } from 'date-fns/locale';

export default function ParsePermissionCountdown({ expiresAt, canParse, isDemoMode = false }) {
    const { t, i18n } = useTranslation();
    const [timeLeft, setTimeLeft] = useState('');
    const [isExpired, setIsExpired] = useState(false);

    useEffect(() => {
        if (!expiresAt) return;

        const updateCountdown = () => {
            const expiry = new Date(expiresAt);
            if (isPast(expiry)) {
                setIsExpired(true);
                setTimeLeft(t('common.expired', 'Expired'));
                return;
            }

            setIsExpired(false);
            // Use the appropriate locale based on the current language
            const locale = i18n.language === 'ru' ? ru : enUS;
            setTimeLeft(formatDistanceToNow(expiry, { locale }));
        };

        updateCountdown();
        const interval = setInterval(updateCountdown, 60000); // Update every minute

        return () => clearInterval(interval);
    }, [expiresAt, t, i18n.language]);

    // Show Demo mode chip when:
    // 1. User is active but doesn't have can_parse permission, OR
    // 2. User's parse permission has expired
    if (isDemoMode || isExpired) {
        return (
            <Tooltip title={t('telegram.demoModeInfo', 'Demo mode: You can only parse groups, not channels')}>
                <Chip
                    icon={<DemoIcon />}
                    label={t('telegram.demoMode', 'Demo Mode')}
                    color="warning"
                    size="small"
                    sx={{ 
                        height: '24px',
                        '& .MuiChip-label': { px: 1 }
                    }}
                />
            </Tooltip>
        );
    }

    if (!canParse) {
        return (
            <Tooltip title={t('telegram.parsePermissionDisabled', 'Parse permission is disabled')}>
                <Chip
                    icon={<BlockIcon />}
                    label={t('telegram.parseDisabled', 'Parse Disabled')}
                    color="default"
                    size="small"
                    sx={{ 
                        height: '24px',
                        '& .MuiChip-label': { px: 1 }
                    }}
                />
            </Tooltip>
        );
    }

    if (!expiresAt) {
        return (
            <Tooltip title={t('telegram.parsePermissionEnabled', 'Parse permission is enabled (no expiration)')}>
                <Chip
                    icon={<TimerIcon />}
                    label={t('telegram.parseEnabled', 'Parse Enabled')}
                    color="success"
                    size="small"
                    sx={{ 
                        height: '24px',
                        '& .MuiChip-label': { px: 1 }
                    }}
                />
            </Tooltip>
        );
    }

    return (
        <Tooltip title={t(
            'telegram.parsePermissionExpires', 
            {
                date: format(new Date(expiresAt), 'dd.MM.yyyy HH:mm')
            },
            `Parse permission expires on ${format(new Date(expiresAt), 'dd.MM.yyyy HH:mm')}`
        )}>
            <Chip
                icon={<TimerIcon />}
                label={`${t('common.left', 'Left')}: ${timeLeft}`}
                color="success"
                size="small"
                sx={{ 
                    height: '24px',
                    '& .MuiChip-label': { px: 1 }
                }}
            />
        </Tooltip>
    );
} 